#!/usr/bin/env bash
# Dialogue cleanup + synthesized (license-free) sound design + 2-pass loudness mastering. Original is never modified.
set -euo pipefail; cd "$(dirname "$0")/.."
IN=input/IMG_0611.mp4; A=audio; mkdir -p $A
DUR=$(ffprobe -v error -show_entries format=duration -of csv=p=0 $IN)
OUTRO_T=$(python3 -c "print(round($DUR-4.0,3))")
# --- Synthesized SFX (generated by FFmpeg, no third-party assets) ---
ffmpeg -hide_banner -v error -y -f lavfi -i "aevalsrc='0.9*sin(2*PI*(46+55*exp(-t*7))*t)*exp(-t*2.6)':d=2.2:s=48000" -af "lowpass=f=180" $A/sfx_impact.wav
ffmpeg -hide_banner -v error -y -f lavfi -i "anoisesrc=color=pink:d=1.6:r=48000:a=0.5" -af "highpass=f=500,lowpass=f=6500,afade=t=in:d=1.0:curve=qsin,afade=t=out:st=1.0:d=0.6:curve=hsin" $A/sfx_whoosh.wav
ffmpeg -hide_banner -v error -y -f lavfi -i "aevalsrc='0.5*sin(2*PI*55*t)+0.3*sin(2*PI*82.41*t)':d=4:s=48000" -af "afade=t=in:d=1.5:curve=qsin,afade=t=out:st=2.0:d=2.0:curve=hsin,lowpass=f=300" $A/sfx_outro_drone.wav
# --- Dialogue chain ---
CHAIN="highpass=f=80,afftdn=nr=9:nf=-38,equalizer=f=250:t=q:w=1.2:g=-1.5,equalizer=f=3200:t=q:w=1:g=1.8,acompressor=threshold=-21dB:ratio=2.5:attack=15:release=220:makeup=2"
MIX="[0:a:0]${CHAIN}[d];[1:a]volume=0.35,adelay=300|300[i];[2:a]volume=0.10,adelay=0|0[w];[3:a]volume=0.12,adelay=$(python3 -c "print(int($OUTRO_T*1000))")|$(python3 -c "print(int($OUTRO_T*1000))")[o];[d][i][w][o]amix=inputs=4:normalize=0:duration=first:dropout_transition=0[m]"
ffmpeg -hide_banner -v error -y -i $IN -i $A/sfx_impact.wav -i $A/sfx_whoosh.wav -i $A/sfx_outro_drone.wav -filter_complex "${MIX};[m]anull[out]" -map "[out]" -ar 48000 -c:a pcm_s24le $A/premaster.wav
# --- 2-pass loudnorm to -14 LUFS / -1.5 dBTP (social platform target) ---
M=$(ffmpeg -hide_banner -nostats -i $A/premaster.wav -af loudnorm=I=-14:TP=-1.5:LRA=11:print_format=json -f null - 2>&1 | sed -n '/^{/,/^}/p')
g(){ echo "$M" | python3 -c "import sys,json;print(json.load(sys.stdin)['$1'])"; }
LN="loudnorm=I=-14:TP=-1.5:LRA=11:measured_I=$(g input_i):measured_TP=$(g input_tp):measured_LRA=$(g input_lra):measured_thresh=$(g input_thresh):offset=$(g target_offset):linear=true"
ffmpeg -hide_banner -v error -y -i $A/premaster.wav -af "${LN},afade=t=in:d=0.25,afade=t=out:st=$(python3 -c "print(round($DUR-2.2,3))"):d=2.2:curve=hsin,alimiter=limit=0.84:level=false" -ar 48000 -c:a pcm_s24le $A/master.wav
ffmpeg -hide_banner -nostats -i $A/master.wav -af ebur128=peak=true -f null - 2>&1 | tail -12
